package goya

import "testing"

func TestCheckedResizableArrayBuffer(t *testing.T) {
	for name, source := range map[string]string{
		"fixed and resizable":               `const fixed=new ArrayBuffer(4);const variable=new ArrayBuffer(4,{maxByteLength:8});const empty=new ArrayBuffer(0,{maxByteLength:0});!fixed.resizable&&fixed.maxByteLength===4&&variable.resizable&&variable.maxByteLength===8&&empty.resizable&&empty.maxByteLength===0;`,
		"growth and zeroing":                `const b=new ArrayBuffer(4,{maxByteLength:12});const a=new Uint8Array(b);a.set([1,2,3,4]);b.resize(8);const first=a.join(",");b.resize(2);b.resize(6);first==="1,2,3,4,0,0,0,0"&&a.join(",")==="1,2,0,0,0,0"&&Number(b.byteLength)===6;`,
		"typed view recovery":               `const b=new ArrayBuffer(8,{maxByteLength:16});const fixed=new Uint16Array(b,2,2),tracking=new Uint16Array(b,2);fixed.set([42,43]);b.resize(4);const out=Number(fixed.length)===0&&Number(fixed.byteLength)===0&&Number(fixed.byteOffset)===0&&fixed[0]===undefined&&Object.keys(fixed).length===0&&Number(tracking.length)===1&&tracking[0]===42;b.resize(8);out&&Number(fixed.length)===2&&Number(fixed.byteOffset)===2&&fixed[0]===42&&fixed[1]===0&&fixed.buffer===b&&Number(tracking.length)===3;`,
		"unaligned tracking end":            `const b=new ArrayBuffer(3,{maxByteLength:8});const a=new Uint16Array(b);const tail=new Uint16Array(b,2);b.resize(5);Number(a.length)===2&&Number(a.byteLength)===4&&Number(tail.length)===1&&Number(tail.byteOffset)===2;`,
		"tracking data view":                `const b=new ArrayBuffer(8,{maxByteLength:16});const fixed=new DataView(b,2,4),tracking=new DataView(b,2);fixed.setUint16(0,42);b.resize(3);let errors=0;for(const f of [()=>fixed.byteLength,()=>fixed.byteOffset,()=>fixed.getUint8(0)]){try{f()}catch(e){if(e instanceof TypeError)errors++}}const before=errors===3&&Number(tracking.byteLength)===1&&Number(tracking.byteOffset)===2;b.resize(8);before&&Number(fixed.byteLength)===4&&Number(fixed.byteOffset)===2&&Number(tracking.byteLength)===6&&fixed.buffer===b;`,
		"zero length offset":                `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b,4),d=new DataView(b,4);b.resize(3);const out=Number(a.length)===0&&Number(a.byteOffset)===0;let rejected=false;try{d.byteLength}catch(e){rejected=e instanceof TypeError}b.resize(4);out&&rejected&&Number(a.byteOffset)===4&&Number(a.length)===0&&Number(d.byteOffset)===4&&Number(d.byteLength)===0;`,
		"resize validation":                 `let effects=0,errors=0;const fixed=new ArrayBuffer(1);const b=new ArrayBuffer(2,{maxByteLength:4});for(const f of [()=>fixed.resize({valueOf(){effects++;return 0}} as any),()=>b.resize(-1),()=>b.resize(5),()=>b.resize(Infinity),()=>new ArrayBuffer(4,{maxByteLength:3}),()=>ArrayBuffer.prototype.resize.call({},1),()=>ArrayBuffer.prototype.resize.call(new Proxy(b,{}),1)]){try{f()}catch(e){if(e instanceof TypeError||e instanceof RangeError)errors++}}errors===7&&effects===0&&Number(b.byteLength)===2;`,
		"constructor order":                 `const log:string[]=[];const target=new Proxy(function(){},{get(t,k,r){if(k==="prototype")log.push("prototype");return Reflect.get(t,k,r)}});Reflect.construct(ArrayBuffer,[{valueOf(){log.push("length");return 1}},{get maxByteLength(){log.push("max");return {valueOf(){log.push("max value");return 2}}}}],target);log.join(",")==="length,max,max value,prototype";`,
		"transfer preserves maximum":        `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a[0]=42;const moved=b.transfer(6);const before=b.detached&&Number(b.byteLength)===0&&b.maxByteLength===0&&b.resizable&&Number(a.length)===0&&a[0]===undefined&&moved.resizable&&moved.maxByteLength===8&&new Uint8Array(moved)[0]===42;moved.resize(8);before&&Number(moved.byteLength)===8&&new Uint8Array(moved)[7]===0;`,
		"fixed transfer":                    `const b=new ArrayBuffer(2,{maxByteLength:4});const moved=b.transferToFixedLength(8);const fixed=new ArrayBuffer(2).transfer(3);b.detached&&!moved.resizable&&Number(moved.byteLength)===8&&moved.maxByteLength===8&&!fixed.resizable&&Number(fixed.byteLength)===3;`,
		"transfer failure leaves original":  `const b=new ArrayBuffer(2,{maxByteLength:4});let rejected=false;try{b.transfer(5)}catch(e){rejected=e instanceof RangeError}rejected&&!b.detached&&Number(b.byteLength)===2;`,
		"detach during resize coercion":     `const b=new ArrayBuffer(2,{maxByteLength:4});let rejected=false;try{b.resize({valueOf(){b.transfer();return 1}} as any)}catch(e){rejected=e instanceof TypeError}rejected&&b.detached;`,
		"detached resize still coerces":     `const b=new ArrayBuffer(2,{maxByteLength:4});b.transfer();let effects=0,rejected=false;try{b.resize({valueOf(){effects++;return 1}} as any)}catch(e){rejected=e instanceof TypeError}rejected&&effects===1;`,
		"slice after resize":                `const b=new ArrayBuffer(8,{maxByteLength:16});new Uint8Array(b).set([1,2,3,4,5,6,7,8]);const copy=b.slice({valueOf(){b.resize(2);return 1}} as any,6);!copy.resizable&&Number(copy.byteLength)===5&&new Uint8Array(copy).join(",")==="2,0,0,0,0";`,
		"data view coercions":               `const b=new ArrayBuffer(8,{maxByteLength:16});const d=new DataView(b);let rejected=false;try{d.setUint32({valueOf(){b.resize(4);return 0}} as any,{valueOf(){b.resize(2);return 42}} as any)}catch(e){rejected=e instanceof RangeError}rejected&&Number(b.byteLength)===2;`,
		"data view prototype side effects":  `const b=new ArrayBuffer(8,{maxByteLength:16});const target=new Proxy(function(){},{get(t,k,r){if(k==="prototype"){b.resize(2);return DataView.prototype}return Reflect.get(t,k,r)}});const tracking=Reflect.construct(DataView,[b],target);Number(tracking.byteLength)===2;`,
		"subarray tracking":                 `const b=new ArrayBuffer(8,{maxByteLength:16});const tracking=new Uint16Array(b,2);const sub=tracking.subarray(1),fixed=tracking.subarray(1,2);b.resize(12);const before=Number(sub.length)===4&&Number(fixed.length)===1;const explicit=new Uint16Array(b,2,2).subarray(1);b.resize(16);before&&Number(sub.length)===6&&Number(fixed.length)===1&&Number(explicit.length)===1;`,
		"iterators track growth":            `const b=new ArrayBuffer(2,{maxByteLength:4});const a=new Uint8Array(b);a.set([1,2]);const it=a.values();const first=it.next().value;b.resize(3);a[2]=3;const rest=Array.from(it);const done=it.next().done;b.resize(4);first===1&&rest.join(",")==="2,3"&&done&&it.next().done;`,
		"iterator intrinsic length":         `const a=new Uint8Array([1,2]);Object.defineProperty(a,"length",{value:0});Array.from(a.values()).join(",")==="1,2";`,
		"fixed iterator recovery":           `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b,0,4);a.set([1,2,3,4]);const it=a.values();const first=it.next().value;b.resize(2);let rejected=false;try{it.next()}catch(e){rejected=e instanceof TypeError}b.resize(4);first===1&&rejected&&it.next().value===2;`,
		"index writes coerce out of bounds": `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b,0,4);b.resize(0);let effects=0;a[0]={valueOf(){effects++;return 42}} as any;effects===1&&a[0]===undefined&&!(0 in a)&&Reflect.ownKeys(a).length===0;`,
		"callback snapshot length":          `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a.set([1,2,3,4]);const values:unknown[]=[];a.forEach((v,i)=>{values.push(v);if(i===0)b.resize(1)});Number(values.length)===4&&values[0]===1&&values.slice(1).every(v=>v===undefined);`,
		"map and filter undefined":          `const b=new ArrayBuffer(24,{maxByteLength:32});const a=new Float64Array(b);a.set([1,2,3]);const mapped=a.map((v,i)=>{if(i===0)b.resize(8);return v});b.resize(24);a.set([1,2,3]);const filtered=a.filter((v,i)=>{if(i===0)b.resize(8);return true});Number(mapped.length)===3&&mapped[0]===1&&Number.isNaN(mapped[1])&&Number.isNaN(mapped[2])&&Number(filtered.length)===3&&filtered[0]===1&&Number.isNaN(filtered[1])&&Number.isNaN(filtered[2]);`,
		"search after resize":               `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a.set([1,2,3,4]);const missing=a.includes(undefined as any,{valueOf(){b.resize(1);return 1}} as any);b.resize(4);const index=a.indexOf(0,{valueOf(){b.resize(0);return 0}} as any);missing&&index===-1;`,
		"at snapshot and join snapshot":     `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a.set([1,2,3,4]);const value=a.at({valueOf(){b.resize(1);return -1}} as any);b.resize(4);a.set([1,2,3,4]);const joined=a.join({toString(){b.resize(1);return ":"}} as any);value===undefined&&joined==="1:::";`,
		"set conversion after resize":       `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);let effects=0;const source={length:3,get 0(){b.resize(1);return 7},get 1(){return {valueOf(){effects++;return 8}}},get 2(){return {valueOf(){effects++;return 9}}}};a.set(source as any);a[0]===7&&effects===2&&Number(a.length)===1;`,
		"fill clamp":                        `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a.fill({valueOf(){b.resize(2);return 42}} as any);a.join(",")==="42,42";`,
		"copyWithin clamp":                  `const b=new ArrayBuffer(6,{maxByteLength:8});const a=new Uint8Array(b);a.set([1,2,3,4,5,6]);a.copyWithin({valueOf(){b.resize(4);return 1}} as any,0,5);a.join(",")==="1,1,2,3";`,
		"sort snapshots values":             `const b=new ArrayBuffer(3,{maxByteLength:8});const a=new Uint8Array(b);a.set([3,1,2]);let compared=0;a.sort((x,y)=>{compared++;b.resize(1);if(x===undefined||y===undefined)throw Error("bad snapshot");return x-y});b.resize(3);compared>0&&a.join(",")==="1,0,0";`,
		"with after shrink":                 `const b=new ArrayBuffer(24,{maxByteLength:32});const a=new Float64Array(b);a.set([1,2,3]);const result=a.with(0,{valueOf(){b.resize(8);return 42}} as any);Number(result.length)===3&&result[0]===42&&Number.isNaN(result[1])&&Number.isNaN(result[2]);`,
		"slice after species resize":        `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);a.set([1,2,3,4]);Object.defineProperty(a,"constructor",{value:{[Symbol.species]:function(length:number){b.resize(2);return new Uint8Array(length)}}});a.slice(1).join(",")==="2,0,0";`,
		"all element kinds":                 `const constructors:any[]=[Int8Array,Uint8Array,Uint8ClampedArray,Int16Array,Uint16Array,Int32Array,Uint32Array,Float16Array,Float32Array,Float64Array,BigInt64Array,BigUint64Array];let passed=0;for(const C of constructors){const size=C.BYTES_PER_ELEMENT;const b=new ArrayBuffer(size*4,{maxByteLength:size*8});const fixed=new C(b,size,2),tracking=new C(b,size);const value=C===BigInt64Array||C===BigUint64Array?42n:42;fixed[0]=value;b.resize(size*2);if(fixed.length!==0||tracking.length!==1||tracking[0]!==value)throw Error(C.name);b.resize(size*4);if(fixed.length!==2||tracking.length!==3||fixed[0]!==value)throw Error(C.name);passed++}passed===12;`,
		"out of bounds methods":             `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b,0,4);b.resize(0);const tasks=[()=>a.at(0),()=>a.copyWithin(0,1),()=>a.entries(),()=>a.every(()=>true),()=>a.fill(1),()=>a.filter(()=>true),()=>a.find(()=>true),()=>a.findIndex(()=>true),()=>a.findLast(()=>true),()=>a.findLastIndex(()=>true),()=>a.forEach(()=>{}),()=>a.includes(1),()=>a.indexOf(1),()=>a.join(),()=>a.keys(),()=>a.lastIndexOf(1),()=>a.map(x=>x),()=>a.reduce(x=>x,0),()=>a.reduceRight(x=>x,0),()=>a.reverse(),()=>a.set([]),()=>a.slice(),()=>a.some(()=>true),()=>a.sort(),()=>a.toLocaleString(),()=>a.toReversed(),()=>a.toSorted(),()=>a.values(),()=>a.with(0,1)];let errors=0;for(const task of tasks){try{task()}catch(e){if(e instanceof TypeError)errors++}}errors===tasks.length;`,
		"extensibility":                     `const b=new ArrayBuffer(4,{maxByteLength:8});const fixed=new Uint8Array(b,0,2),tracking=new Uint8Array(b);const first=!Reflect.preventExtensions(fixed)&&!Reflect.preventExtensions(tracking)&&Object.isExtensible(fixed)&&Object.isExtensible(tracking);b.resize(0);let rejected=false;try{Object.freeze(tracking)}catch(e){rejected=e instanceof TypeError}first&&rejected&&!Reflect.preventExtensions(fixed)&&Reflect.preventExtensions(new Uint8Array(0));`,
		"filter after detach":               `const b=new ArrayBuffer(24);const a=new Float64Array(b);a.set([1,2,3]);const result=a.filter((v,i)=>{if(i===0)b.transfer();return true});result.length===3&&result[0]===1&&Number.isNaN(result[1])&&Number.isNaN(result[2]);`,
		"bigint undefined conversion":       `const b=new ArrayBuffer(16,{maxByteLength:24});const a=new BigInt64Array(b);let rejected=false,calls=0;try{a.filter((v,i)=>{calls++;if(i===0)b.resize(8);return true})}catch(e){rejected=e instanceof TypeError}rejected&&calls===2;`,
		"from and of use indexed writes":    `const b=new ArrayBuffer(4,{maxByteLength:8});const a=new Uint8Array(b);function C(){return a}let effects=0;const result=Uint8Array.from.call(C as any,[1,2,3,4],(v,i)=>{effects++;if(i===0)b.resize(1);return Number(v)});b.resize(4);const value={valueOf(){effects++;b.resize(1);return 7}};const second=Uint8Array.of.call(C as any,value as any,value as any,value as any);result===a&&second===a&&effects===7&&a[0]===7;`,
		"sort comparator signed zero":       `const a=new Uint8Array([2,1]);a.sort(()=>-0);a[0]===2&&a[1]===1;`,
	} {
		t.Run(name, func(t *testing.T) {
			value, err := New().RunString(source)
			if err != nil || !value.ToBoolean() {
				t.Fatalf("resizable buffer: %v %v", value, err)
			}
		})
	}
}
